)

 AND ( 
  ( wp_postmeta.meta_key = 'k' AND wp_postmeta.meta_value NOT LIKE '%part%' )
)

 AND ( 
  ( wp_postmeta.meta_key = 'p' AND CAST(wp_postmeta.meta_value AS DECIMAL(10,2)) > '9.5' )
)

 AND ( 
  ( wp_postmeta.meta_key = 'd' AND CAST(wp_postmeta.meta_value AS DATE) <= '2026-01-01' )
)

